from base import C

FICHAS = [
C('ranson', 'Criterios de Ranson (pancreatitis aguda)', 'cr1',
  'Escala pronóstica de la pancreatitis aguda con 5 criterios al ingreso y 6 a las 48 horas. Cada criterio cumplido suma un punto; hay umbrales distintos para la pancreatitis biliar.',
  ['Al ingreso (no biliar): edad > 55 años; leucocitos > 16.000/mm³; glucemia > 200 mg/dl; LDH > 350 UI/L; AST > 250 UI/L.',
   'A las 48 horas (no biliar): caída del hematocrito > 10 puntos; aumento de urea (BUN) > 5 mg/dl; calcio < 8 mg/dl; PaO₂ < 60 mmHg; déficit de base > 4 mEq/L; secuestro de líquidos > 6 L.',
   'Pancreatitis biliar: edad > 70; leucocitos > 18.000; glucemia > 220; LDH > 400; AST > 250; a las 48 h, hematocrito, BUN > 2 mg/dl, calcio, déficit de base > 5 y secuestro > 4 L.'],
  ['Se completa en dos momentos: ingreso y 48 horas; no se puede calcular de entrada en su totalidad.'],
  [('Puntaje', [('0 a 2', 'Gravedad baja: mortalidad ≈ 1 a 3 %.'), ('3 a 4', 'Mortalidad ≈ 15 %.'), ('5 a 6', 'Pancreatitis grave: mortalidad ≈ 40 %.'), ('≥ 7', 'Muy grave: mortalidad > 50 %.')])],
  ['Hoy se complementa con la clasificación de Atlanta revisada y el BISAP; es una escala histórica con porcentajes aproximados.'], None,
  ('Ranson JH et al. Surg Gynecol Obstet 1974;139:69; Guía de pancreatitis aguda', 'Atlanta 2012 / Guía argentina de pancreatitis aguda', 1974), ['ranson', 'pancreatitis', 'gravedad'], 'ranson'),

C('atlanta-2012', 'Clasificación de Atlanta revisada (pancreatitis aguda)', 'cr1',
  'Clasifica la pancreatitis aguda por gravedad según la falla orgánica y las complicaciones locales; el diagnóstico exige 2 de 3 criterios.',
  ['Diagnóstico (2 de 3): dolor abdominal típico en epigastrio; lipasa o amilasa > 3 veces el límite superior normal; hallazgos característicos en imágenes.',
   'Leve: sin falla orgánica ni complicaciones locales o sistémicas.',
   'Moderadamente grave: falla orgánica transitoria (< 48 h) o complicaciones locales/sistémicas sin falla persistente.',
   'Grave: falla orgánica persistente (> 48 h) de uno o más órganos.',
   'Falla orgánica: puntaje ≥ 2 en el sistema respiratorio, cardiovascular o renal de la escala de Marshall modificada.'],
  ['Colección aguda, necrosis y pseudoquiste se definen con tomografía con contraste (idealmente a partir de las 72 horas).'],
  [('Conducta', [('Leve', 'Dieta oral temprana, analgesia e hidratación; alta cuando tolera la vía oral.'), ('Moderada a grave', 'Reposición dirigida, soporte de órganos, nutrición enteral y evaluación de necrosis infectada.')])],
  ['La falla orgánica persistente es el principal determinante de mortalidad.'], None,
  ('Revised Atlanta Classification (Banks PA et al., Gut 2013;62:102)', 'Atlanta Working Group / IAP-APA', 2012), ['atlanta', 'pancreatitis']),

C('bisap', 'Score BISAP (pancreatitis aguda)', 'cr1',
  'Predice mortalidad intrahospitalaria en las primeras 24 horas con 5 variables simples.',
  ['B: BUN > 25 mg/dl.', 'I: alteración del estado mental (Glasgow < 15).', 'S: SIRS (2 o más criterios).', 'A: edad > 60 años.', 'P: derrame pleural (Pleural effusion).'],
  ['Un punto por cada criterio, evaluados en las primeras 24 horas.'],
  [('Puntaje', [('0 a 2', 'Riesgo bajo: mortalidad < 2 %.'), ('≥ 3', 'Riesgo alto: mortalidad ≈ 5 a 20 % y mayor riesgo de falla orgánica.')])],
  ['Es una herramienta pronóstica, no reemplaza la reevaluación clínica seriada.'], None,
  ('Wu BU et al. Gut 2008;57:1698', 'Banks PA / American College of Gastroenterology', 2008), ['bisap', 'pancreatitis'], 'bisap'),

C('alvarado', 'Escala de Alvarado (apendicitis aguda)', 'cr1',
  'Puntaje de 10 puntos que estima la probabilidad de apendicitis aguda en el dolor de fosa ilíaca derecha (regla mnemotécnica MANTRELS).',
  ['Migración del dolor a la fosa ilíaca derecha: 1.', 'Anorexia: 1.', 'Náuseas o vómitos: 1.', 'Sensibilidad en fosa ilíaca derecha: 2.', 'Signo de rebote: 1.', 'Fiebre ≥ 37,3 °C: 1.', 'Leucocitosis > 10.000/mm³: 2.', 'Neutrofilia > 75 %: 1.'],
  ['Se calcula con la clínica y un hemograma; no requiere imágenes.'],
  [('Puntaje', [('1 a 4', 'Apendicitis improbable.'), ('5 a 6', 'Posible: solicitar ecografía o tomografía.'), ('7 a 8', 'Probable: evaluación quirúrgica.'), ('9 a 10', 'Muy probable.')])],
  ['Rinde peor en mujeres en edad fértil y en niños: apoyarse en imágenes.'], None,
  ('Alvarado A. Ann Emerg Med 1986;15:557; Jerusalem Guidelines 2020', 'World Society of Emergency Surgery (WSES)', 2020), ['alvarado', 'apendicitis', 'mantrels'], 'alvarado'),

C('tokio-colecistitis', 'Criterios de Tokio TG18: colecistitis aguda', 'cr1',
  'Criterios diagnósticos y de gravedad de la colecistitis aguda (Tokyo Guidelines 2018).',
  ['A. Signos locales: signo de Murphy; masa, dolor o defensa en hipocondrio derecho.', 'B. Signos sistémicos: fiebre; PCR elevada; leucocitosis.', 'C. Imágenes características de colecistitis aguda.',
   'Sospecha: un criterio A + uno B. Diagnóstico definitivo: un A + un B + C.'],
  ['Gravedad: Grado III (grave) con disfunción de un órgano: hipotensión que requiere vasopresores, alteración de conciencia, PaO₂/FiO₂ < 300, oliguria o creatinina > 2 mg/dl, INR > 1,5 o plaquetas < 100.000.',
   'Grado II (moderada): leucocitos > 18.000, masa palpable, evolución > 72 horas o inflamación local marcada (gangrena, absceso, peritonitis biliar).'],
  [('Gravedad y conducta', [('Grado I (leve)', 'Colecistectomía laparoscópica temprana.'), ('Grado II', 'Colecistectomía temprana en centro con experiencia; si no, drenaje y antibióticos.'), ('Grado III', 'Soporte de órganos y drenaje percutáneo; cirugía diferida según evolución.')])],
  ['La antibioticoterapia y el momento de la cirugía dependen del grado y de los factores de riesgo del paciente.'], None,
  ('Tokyo Guidelines 2018 (TG18): criterios de colecistitis aguda', 'Tokyo Guidelines Revision Committee', 2018), ['tokio', 'tg18', 'colecistitis'], None),

C('tokio-colangitis', 'Criterios de Tokio TG18: colangitis aguda', 'cr1',
  'Criterios diagnósticos y de gravedad de la colangitis aguda (Tokyo Guidelines 2018).',
  ['A. Inflamación sistémica: fiebre o escalofríos (> 38 °C); leucocitos < 4.000 o > 10.000; PCR ≥ 1 mg/dl.', 'B. Colestasis: ictericia (bilirrubina ≥ 2 mg/dl); pruebas hepáticas > 1,5 veces el límite superior (FA, GGT, AST, ALT).',
   'C. Imágenes: dilatación biliar o evidencia de la causa (estenosis, litiasis, stent).', 'Sospecha: un A + un B o C. Diagnóstico definitivo: un A + un B + un C.'],
  ['Grado III: disfunción de órgano (cardiovascular, neurológica, respiratoria, renal, hepática o hematológica).', 'Grado II: 2 de 5: leucocitos > 12.000 o < 4.000; fiebre ≥ 39 °C; edad ≥ 75; bilirrubina ≥ 5 mg/dl; hipoalbuminemia.'],
  [('Conducta según gravedad', [('Grado I', 'Antibióticos; drenaje biliar si no mejora en 24 horas.'), ('Grado II', 'Drenaje biliar precoz (CPRE).'), ('Grado III', 'Soporte de órganos y drenaje biliar urgente.')])],
  ['La tríada de Charcot (fiebre, ictericia y dolor) es poco sensible: ante la sospecha aplicar los criterios completos.'], None,
  ('Tokyo Guidelines 2018 (TG18): criterios de colangitis aguda', 'Tokyo Guidelines Revision Committee', 2018), ['tokio', 'tg18', 'colangitis', 'charcot']),

C('glasgow-blatchford', 'Score de Glasgow-Blatchford (hemorragia digestiva alta)', 'cr1',
  'Identifica a los pacientes con hemorragia digestiva alta que necesitan intervención y a los de muy bajo riesgo que pueden manejarse de forma ambulatoria.',
  ['Urea (BUN) en mg/dl: 18,2 a 22,3: 2; 22,4 a 27,9: 3; 28 a 69,9: 4; ≥ 70: 6.', 'Hemoglobina en varones: 12 a 12,9: 1; 10 a 11,9: 3; < 10: 6. En mujeres: 10 a 11,9: 1; < 10: 6.',
   'Presión sistólica: 100 a 109: 1; 90 a 99: 2; < 90: 3.', 'Otros: frecuencia cardíaca ≥ 100: 1; melena: 1; síncope: 2; enfermedad hepática: 2; insuficiencia cardíaca: 2.'],
  ['Se calcula antes de la endoscopia, con datos clínicos y de laboratorio.'],
  [('Puntaje', [('0 a 1', 'Riesgo muy bajo: alta ambulatoria y endoscopia diferida.'), ('≥ 2', 'Internación y endoscopia en las primeras 24 horas.')])],
  ['Máximo de 23 puntos. Complementar con el Rockall tras la endoscopia.'], None,
  ('Blatchford O et al. Lancet 2000;356:1318; Barkun A et al. Ann Intern Med 2019', 'Consenso internacional de HDA no varicosa / ESGE', 2021), ['glasgow blatchford', 'hda', 'hemorragia digestiva'], 'glasgow-blatchford'),

C('forrest', 'Clasificación de Forrest (úlcera sangrante)', 'cr1',
  'Clasifica los estigmas endoscópicos de sangrado de la úlcera péptica y orienta la necesidad de tratamiento endoscópico.',
  ['Ia: sangrado en chorro (arterial).', 'Ib: sangrado en napa o babeo.', 'IIa: vaso visible no sangrante.', 'IIb: coágulo adherido.', 'IIc: base con puntos de hematina (mancha plana).', 'III: base limpia, sin estigmas.'],
  ['Se informa en la endoscopia digestiva alta de la hemorragia.'],
  [('Conducta', [('Ia, Ib, IIa', 'Alto riesgo: tratamiento endoscópico más inhibidor de la bomba de protones en infusión o dosis altas.'), ('IIb', 'Retirar el coágulo y tratar la lesión subyacente si hay estigmas de alto riesgo.'), ('IIc y III', 'Bajo riesgo: inhibidor de la bomba de protones por vía oral y alta temprana.')])],
  ['El riesgo de resangrado sin tratamiento va de ≈ 40 a 55 % (Ia, Ib, IIa) hasta ≈ 5 % (III).'], None,
  ('Forrest JA et al. Lancet 1974;2:394; Guías ESGE 2021', 'Sociedad Europea de Endoscopia Gastrointestinal (ESGE)', 2021), ['forrest', 'ulcera', 'hda']),

C('rockall', 'Score de Rockall completo', 'cr1',
  'Estima el riesgo de resangrado y de mortalidad después de la endoscopia en la hemorragia digestiva alta.',
  ['Edad: < 60: 0; 60 a 79: 1; ≥ 80: 2.', 'Shock: ninguno: 0; taquicardia (FC ≥ 100, PAS ≥ 100): 1; hipotensión (PAS < 100): 2.', 'Comorbilidad: ninguna: 0; cardíaca u otra mayor: 2; insuficiencia renal o hepática, cáncer diseminado: 3.',
   'Diagnóstico: Mallory-Weiss o sin lesión: 0; otros: 1; neoplasia: 2.', 'Estigmas: ninguno o mancha plana: 0; sangre, coágulo adherido o vaso visible: 2.'],
  ['Se completa con la información de la endoscopia.'],
  [('Puntaje', [('≤ 2', 'Riesgo bajo: alta temprana.'), ('3 a 4', 'Riesgo intermedio.'), ('≥ 5', 'Riesgo alto de resangrado y mortalidad.')])],
  [], None, ('Rockall TA et al. Gut 1996;38:316', 'Consenso internacional de HDA no varicosa', 1996), ['rockall'], 'rockall'),

C('hinchey', 'Clasificación de Hinchey (diverticulitis aguda complicada)', 'cr1',
  'Clasifica la gravedad de la diverticulitis aguda según el hallazgo de absceso o peritonitis.',
  ['I: absceso pericólico o mesocólico.', 'II: absceso pélvico, intraabdominal a distancia o retroperitoneal.', 'III: peritonitis purulenta generalizada.', 'IV: peritonitis fecal.'],
  ['Se establece con tomografía de abdomen y pelvis o durante la cirugía.'],
  [('Conducta', [('Hinchey I (absceso < 3 cm)', 'Antibióticos y reposo intestinal.'), ('Hinchey I a II con absceso ≥ 3 a 4 cm', 'Drenaje percutáneo guiado por imágenes más antibióticos.'), ('Hinchey III a IV', 'Cirugía urgente: resección con o sin anastomosis; Hartmann si hay inestabilidad.')])],
  ['Si no mejora con tratamiento médico en 48 a 72 horas, reevaluar con imágenes.'], None,
  ('Hinchey EJ et al. Adv Surg 1978;12:85; Guía de enfermedad diverticular', 'Sociedad Argentina de Coloproctología / ASCRS', 2020), ['hinchey', 'diverticulitis']),

C('garden', 'Clasificación de Garden (fractura de cuello femoral)', 'cr1',
  'Clasifica las fracturas intracapsulares del cuello femoral según el desplazamiento y orienta entre osteosíntesis y artroplastia.',
  ['I: incompleta o en valgo impactada.', 'II: completa, sin desplazamiento.', 'III: completa, con desplazamiento parcial (varo).', 'IV: completa, con desplazamiento total.'],
  ['Radiografía de pelvis frente y cadera de perfil.'],
  [('Conducta', [('Garden I y II', 'Osteosíntesis (tornillos canulados) precoz.'), ('Garden III y IV', 'En ancianos, artroplastia; en jóvenes, reducción y osteosíntesis urgente.')])],
  ['Alto riesgo de necrosis avascular en las desplazadas: la cirugía precoz mejora el pronóstico.'], None,
  ('Garden RS. J Bone Joint Surg Br 1961;43:647; Manual CTO de Traumatología', 'Manual CTO de Medicina y Cirugía (traumatología)', 2018), ['garden', 'cadera', 'fractura de cadera']),

C('salter-harris', 'Clasificación de Salter-Harris (fracturas fisarias)', 'cr1',
  'Clasifica las fracturas que comprometen la placa de crecimiento en niños (regla mnemotécnica SALTR).',
  ['I (Slipped): separación a través de la fisis.', 'II (Above): fisis y metáfisis (fragmento de Thurston-Holland); es la más frecuente.', 'III (Lower): fisis y epífisis, intraarticular.', 'IV (Through): metáfisis, fisis y epífisis.', 'V (Rammed): compresión de la fisis.'],
  ['Radiografía en dos planos y comparativa si hay duda.'],
  [('Pronóstico', [('I y II', 'Buen pronóstico; reducción cerrada e inmovilización.'), ('III y IV', 'Intraarticulares: reducción anatómica, a menudo quirúrgica.'), ('V', 'Peor pronóstico: riesgo de cierre fisario precoz y deformidad.')])],
  ['Control prolongado: pueden aparecer deformidades o discrepancia de longitud tras la consolidación.'], None,
  ('Salter RB, Harris WR. J Bone Joint Surg Am 1963;45:587', 'Manual de Ortopedia y Traumatología (Orrego y Morán)', 2014), ['salter harris', 'fisis', 'fractura pediátrica']),

C('ottawa-tobillo', 'Reglas de Ottawa (tobillo y pie)', 'cr1',
  'Reglas de decisión clínica para indicar radiografía en el traumatismo de tobillo o de pie y evitar estudios innecesarios.',
  ['Tobillo: dolor en la zona maleolar y uno de estos: sensibilidad ósea en el borde posterior o en la punta del maléolo lateral o medial (últimos 6 cm), o incapacidad de dar 4 pasos.',
   'Pie: dolor en el mediopié y uno de estos: sensibilidad ósea en la base del 5.º metatarsiano o en el hueso navicular, o incapacidad de dar 4 pasos.'],
  ['Se aplica en adultos con traumatismo agudo, sin intoxicación ni lesiones distractoras.'],
  [('Resultado', [('Negativa', 'Sensibilidad cercana al 100 %: no hace falta radiografía.'), ('Positiva', 'Solicitar radiografía de tobillo o de pie.')])],
  ['No es válida en menores de 18 años de forma estricta, embarazo, déficit neurológico o intoxicación.'], None,
  ('Stiell IG et al. JAMA 1994;271:827 (Ottawa Ankle Rules)', 'Ottawa Hospital Research Institute', 1994), ['ottawa', 'tobillo', 'esguince']),

C('nexus', 'Criterios NEXUS (columna cervical)', 'cr1',
  'Permite descartar lesión cervical clínicamente significativa sin imágenes cuando se cumplen cinco criterios.',
  ['Sin dolor a la palpación en la línea media cervical.', 'Sin déficit neurológico focal.', 'Estado de alerta normal.', 'Sin intoxicación.', 'Sin lesión dolorosa que distraiga.'],
  ['Se cumple si se reúnen los cinco criterios (bajo riesgo): no requiere imágenes.'],
  [('Resultado', [('Cumple los 5', 'Se puede liberar la columna cervical clínicamente.'), ('No cumple alguno', 'Imágenes (tomografía) y mantener la inmovilización.')])],
  ['La Regla Canadiense de la columna cervical es otra alternativa validada (edad ≥ 65, mecanismo peligroso o parestesias son de alto riesgo).'], None,
  ('Hoffman JR et al. N Engl J Med 2000;343:94; Consenso CISReMET sobre restricción del movimiento espinal', 'ATLS 10.ª ed. / CISReMET', 2021), ['nexus', 'cervical', 'trauma']),

C('shock-atls', 'Clases de shock hemorrágico (ATLS)', 'cr1',
  'Clasifica la hemorragia según el volumen perdido y los signos clínicos para guiar la reanimación.',
  ['Clase I: pérdida < 15 % (< 750 ml); frecuencia cardíaca normal; presión normal.', 'Clase II: 15 a 30 % (750 a 1.500 ml); FC 100 a 120; presión de pulso disminuida.', 'Clase III: 30 a 40 % (1.500 a 2.000 ml); FC 120 a 140; hipotensión; confusión.', 'Clase IV: > 40 % (> 2.000 ml); FC > 140; hipotensión marcada; letargo.'],
  ['Valorar frecuencia cardíaca, presión, diuresis, estado mental y perfusión; el índice de shock (FC/PAS ≥ 0,9) ayuda a detectarlo.'],
  [('Conducta', [('Clase I a II', 'Cristaloides y control del foco de sangrado.'), ('Clase III a IV', 'Control urgente de la hemorragia, protocolo de transfusión masiva y hemoderivados en proporción balanceada.')])],
  ['Los ancianos, los atletas y quienes usan betabloqueantes pueden no taquicardizar: no confiar solo en la frecuencia cardíaca.'], None,
  ('ATLS (Advanced Trauma Life Support) 10.ª ed.', 'American College of Surgeons / Asociación Argentina de Cirugía', 2018), ['shock', 'atls', 'hemorragia']),

C('asa', 'Clasificación del estado físico ASA', 'cr1',
  'Valora el estado físico del paciente antes de la anestesia y se asocia al riesgo perioperatorio.',
  ['ASA I: paciente sano.', 'ASA II: enfermedad sistémica leve, sin limitación funcional.', 'ASA III: enfermedad sistémica grave con limitación funcional.', 'ASA IV: enfermedad grave con amenaza constante para la vida.', 'ASA V: moribundo que no sobrevivirá sin la operación.', 'ASA VI: muerte encefálica, donante de órganos.', 'Sufijo E: cirugía de urgencia.'],
  ['Se asigna en la consulta preanestésica y se registra en el consentimiento y la historia clínica.'],
  [('Uso', [('Riesgo', 'A mayor clase, mayor riesgo de complicaciones y mortalidad perioperatoria.'), ('Limitación', 'Es una valoración subjetiva: no reemplaza otros índices como el RCRI.')])],
  [], None, ('ASA Physical Status Classification System (actualización 2020)', 'American Society of Anesthesiologists / Asociación de Anestesia, Analgesia y Reanimación de Buenos Aires (AAARBA)', 2020), ['asa', 'anestesia', 'riesgo quirurgico']),

C('mallampati', 'Clasificación de Mallampati (vía aérea)', 'cr1',
  'Predice la dificultad de intubación según las estructuras visibles de la orofaringe con la boca abierta y la lengua protruida.',
  ['Clase I: se ven paladar blando, úvula y pilares.', 'Clase II: paladar blando y úvula.', 'Clase III: paladar blando y base de la úvula.', 'Clase IV: solo paladar duro.'],
  ['Paciente sentado, cabeza en posición neutra, boca abierta al máximo y lengua afuera, sin fonación.'],
  [('Interpretación', [('Clases I y II', 'Intubación predicha como fácil.'), ('Clases III y IV', 'Posible vía aérea difícil: preparar material y plan alternativo.')])],
  ['Se combina con la distancia tiromentoniana, la apertura bucal y la movilidad cervical para valorar la vía aérea.'], None,
  ('Mallampati SR et al. Can Anaesth Soc J 1985;32:429', 'American Society of Anesthesiologists, Practice Guidelines for Management of the Difficult Airway', 2022), ['mallampati', 'via aerea', 'intubacion']),

C('profundidad-quemaduras', 'Profundidad de las quemaduras', 'cr1',
  'Clasifica la quemadura por la profundidad del daño cutáneo, que determina el dolor, la cicatrización y la necesidad de injerto.',
  ['Primer grado (superficial): solo epidermis; eritema, doloroso, sin ampollas.', 'Segundo grado superficial: dermis papilar; ampollas, base rosada y húmeda, muy dolorosa; cicatriza en 2 semanas.',
   'Segundo grado profundo: dermis reticular; base blanquecina o moteada, menos dolorosa; cicatriza en más de 3 semanas y suele requerir injerto.', 'Tercer grado (espesor total): piel acartonada, blanca o carbonizada, indolora.'],
  ['Se complementa con la superficie corporal quemada (regla de los 9 de Wallace o Lund-Browder).'],
  [('Derivación', [('Criterios generales', 'Quemaduras de espesor total, de cara, manos, pies, genitales o articulaciones, eléctricas, químicas, inhalatorias o con superficie extensa: derivar a un centro de quemados.')])],
  ['La profundidad puede progresar en las primeras 48 horas: reevaluar.'], None,
  ('ATLS 10.ª ed. y American Burn Association', 'Asociación Argentina de Quemaduras', 2018), ['quemaduras', 'profundidad', 'wallace']),

C('gartland', 'Clasificación de Gartland (fractura supracondílea de húmero)', 'cr1',
  'Clasifica la fractura supracondílea pediátrica de codo según el desplazamiento y guía la conducta.',
  ['Tipo I: sin desplazamiento.', 'Tipo II: desplazada con cortical posterior conservada.', 'Tipo III: completamente desplazada, sin contacto cortical.'],
  ['Radiografía de codo en dos planos; evaluar siempre el estado neurovascular (arteria braquial, nervio interóseo anterior).'],
  [('Conducta', [('Tipo I', 'Inmovilización con férula posterior.'), ('Tipo II', 'Reducción cerrada y fijación, según el grado.'), ('Tipo III', 'Reducción y fijación con clavijas percutáneas, urgente.')])],
  ['Vigilar el síndrome compartimental y la lesión vascular o nerviosa.'], None,
  ('Gartland JJ. Surg Gynecol Obstet 1959;109:145', 'Manual de Ortopedia y Traumatología (Orrego y Morán)', 2014), ['gartland', 'supracondilea', 'codo']),

C('glasgow', 'Escala de coma de Glasgow', 'cr1',
  'Valora el nivel de conciencia según la respuesta ocular, verbal y motora (3 a 15 puntos).',
  ['Apertura ocular: espontánea 4; a la voz 3; al dolor 2; ninguna 1.', 'Respuesta verbal: orientada 5; confusa 4; palabras inapropiadas 3; sonidos 2; ninguna 1.', 'Respuesta motora: obedece 6; localiza el dolor 5; retira 4; flexión anormal 3; extensión 2; ninguna 1.'],
  ['Se registra la mejor respuesta de cada categoría y se anota el desglose (por ejemplo, O3 V4 M5).'],
  [('Gravedad del traumatismo craneoencefálico', [('13 a 15', 'Leve.'), ('9 a 12', 'Moderado: tomografía y observación.'), ('≤ 8', 'Grave: asegurar la vía aérea y derivar a neurocirugía.')])],
  ['Una caída de 2 o más puntos es signo de alarma de deterioro neurológico.'], None,
  ('Teasdale G, Jennett B. Lancet 1974;2:81; ATLS 10.ª ed.', 'American College of Surgeons / Asociación Argentina de Neurocirugía', 2018), ['glasgow', 'coma', 'tce', 'gcs'], 'glasgow'),
]
